insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_theatre4_v1'
from (values
('117.318.c.1.A',3,'A senior invents a new warm-up sequence for the company, then leads it before each tech rehearsal. She is doing what?','["Creating and demonstrating preparation techniques", "Counting house seats", "Auditing the budget", "Painting a drop"]'::jsonb,0,'Leaders design and model warm-ups.','original'),
('117.318.c.1.A',3,'What should a well-designed company warm-up include?','["Only a lecture", "Physical, vocal and focus components", "Only a costume fitting", "Only a snack"]'::jsonb,1,'Complete warm-ups prepare body, voice and mind.','original'),
('117.318.c.1.B',4,'A student choreographs a crowd transition in which twelve actors cross the stage in layered tempos, then teaches it to the cast. She is doing what?','["Writing a review", "Editing film", "Devising and modeling stage movement", "Selling ads"]'::jsonb,2,'Devising creates the movement; modeling teaches it.','original'),
('117.318.c.1.B',4,'Which skill is essential for modeling a movement sequence for others?','["Random changes", "Silence", "Vague gestures", "Clear demonstration and precise cues"]'::jsonb,3,'Models must be clear and repeatable.','original'),
('117.318.c.1.C',3,'A mentor actor shows a younger cast member how breath, inflection and clean consonants carry meaning. She is doing what?','["Modeling proper vocal techniques", "Reading a review", "Setting light cues", "Hiding technique"]'::jsonb,0,'Modeling teaches technique by example.','original'),
('117.318.c.1.C',3,'Which change in inflection signals a question?','["A loud shout", "A rising pitch at the end of the sentence", "A dropped whisper only", "A steady monotone"]'::jsonb,1,'Rising pitch often marks questions.','original'),
('117.318.c.1.D',4,'A student charts how a three-act play builds tension and how a one-hour TV episode places commercial breaks. She is comparing what?','["Costume fabrics", "Ticket stubs", "The structure of theatre with that of television", "Parking lots"]'::jsonb,2,'Structures differ across media.','original'),
('117.318.c.1.D',4,'Which structural difference separates film from live theatre?','["There is no script", "Actors never rehearse", "There are no characters", "Scenes can be assembled through editing rather than played continuously"]'::jsonb,3,'Editing is a film structure tool.','original'),
('117.318.c.1.E',4,'A student explains that Restoration comedy used asides and elaborate speech that audiences of that era expected. She is evaluating what?','["Theatrical conventions of a particular period", "Parking rules", "Modern emojis", "Lobby snacks"]'::jsonb,0,'Conventions vary by period.','original'),
('117.318.c.1.E',4,'Which convention is associated with Greek tragedy?','["Film close-ups", "A chorus commenting on the action", "A realistic living room set", "A fourth wall"]'::jsonb,1,'The chorus is a Greek convention.','original'),
('117.318.c.1.F',4,'A director realizes that changing the set''s color has forced her to revise lighting, costume and makeup. She has evaluated what?','["A seating chart", "A budget memo", "The interdependence of all theatrical elements", "A scheduling error"]'::jsonb,2,'Elements depend on each other.','original'),
('117.318.c.1.F',4,'Why do directors hold design meetings before rehearsals begin?','["To cut actors", "To lengthen the season", "To avoid decisions", "To align all elements with one unified concept"]'::jsonb,3,'Alignment preserves unity.','original'),
('117.318.c.1.G',3,'A veteran actor teaches the cast to memorize by linking lines to physical actions and objectives. She is doing what?','["Modeling memorization skills", "Reading reviews", "Skipping lines", "Ignoring scripts"]'::jsonb,0,'Modeling shares effective methods.','original'),
('117.318.c.1.G',3,'Which approach reinforces memory most effectively before opening night?','["Ignoring cues", "Frequent short runs of lines with action", "Skipping rehearsals", "One long cram"]'::jsonb,1,'Spaced practice with action works best.','original'),
('117.318.c.2.A',3,'A lead actor invites the director to coordinate a safe way to perform a falling moment, including mats and spotters. She is modeling what?','["Careless risk", "Showing off", "Safe, appropriate techniques for physical expression", "Silence"]'::jsonb,2,'Modeling safe practice sets a standard.','original'),
('117.318.c.2.A',3,'A company leader encourages members to name their limits before an emotional scene. This models what?','["Ignoring feelings", "Forcing the scene", "Cutting rehearsal", "Safe emotional expression"]'::jsonb,3,'Naming limits supports safe expression.','original'),
('117.318.c.2.B',4,'A student ensemble member deliberately changes her pacing to reveal a character''s hesitation and sees the audience grow quiet. She is demonstrating what?','["Creativity and its effect on an audience", "Stage fright", "Boredom", "Late arrival"]'::jsonb,0,'Creative choices shape audience response.','original'),
('117.318.c.2.B',4,'What shows that a creative choice affected the audience?','["Program length", "A visible shift in their attention or reaction", "Seat color", "Ticket price"]'::jsonb,1,'Reaction shows effect.','original'),
('117.318.c.2.C',4,'A student analyzes a character in a Brechtian epic play and a character in a realistic drama, then explains how each should be played. She is doing what?','["Reading a menu", "Listing props only", "Analyzing and interpreting characters from various genres and styles", "Cutting scenes"]'::jsonb,2,'Interpretation depends on style.','original'),
('117.318.c.2.C',4,'How might an actor adapt physicality between farce and naturalism?','["Identical movement", "No gestures at all", "Only stillness", "Larger, faster gestures in farce and subtler behavior in naturalism"]'::jsonb,3,'Style shapes physicality.','original'),
('117.318.c.2.D',4,'An actor studies a Chekhov scene''s subtext and plays the unspoken tension while delivering polite lines. She is doing what?','["Interpreting a scripted scene to portray believable characters", "Ignoring the script", "Reading a review", "Improvising something else"]'::jsonb,0,'Subtext supports believability.','original'),
('117.318.c.2.D',4,'Which choice adds believability in a stylized scripted scene?','["Ignoring the style", "Committing to the style while grounding the character''s goals", "Dropping the script", "Playing it as a joke"]'::jsonb,1,'Commitment plus motivation.','original'),
('117.318.c.2.E',4,'A playwriting team draws a set of scenarios from a local oral-history project and drafts an original script. They are doing what?','["Reciting a classic", "Selling ads", "Creating imaginative scripts and scenarios collaboratively", "Sewing costumes"]'::jsonb,2,'Original scripts can be devised together.','original'),
('117.318.c.2.E',4,'What does a strong original scenario need?','["Only description", "Random events", "No structure", "Clear characters, conflict and stakes"]'::jsonb,3,'Conflict drives scenarios.','original'),
('117.318.c.3.A',3,'A student designs a lighting look for an improvised scene, testing angles and intensity for safety and effect. She is doing what?','["Experimenting with technical elements safely and effectively", "Skipping tech", "Breaking equipment", "Ignoring risk"]'::jsonb,0,'Safe experimentation informs design.','original'),
('117.318.c.3.A',3,'Which habit reflects safe experimentation with theatrical technology?','["Skipping power checks", "Testing a new effect on a small scale first", "Blocking exits", "Plugging in everything at once"]'::jsonb,1,'Small-scale tests reduce risk.','original'),
('117.318.c.3.B',4,'A student reads a script closely, marks character wants and directs a three-minute scene from it. She is doing what?','["Selling tickets", "Sewing a costume", "Analyzing and evaluating a dramatic text and directing a brief scene", "Operating sound"]'::jsonb,2,'Analysis leads to directing choices.','original'),
('117.318.c.3.B',4,'What is a first step in directing a brief scene?','["Print programs", "Order costumes", "Count seats", "Identify each character''s objective and the scene''s turning point"]'::jsonb,3,'Objectives and turning points guide the staging.','original'),
('117.318.c.3.C',4,'A director avoids changing the playwright''s central message while updating the setting. She is honoring what?','["Her responsibility to the author''s intent", "A prop list", "The ticket price", "The seating plan"]'::jsonb,0,'Directors serve the text.','original'),
('117.318.c.3.C',4,'A director''s responsibility to the author includes what?','["Rewriting without regard", "Respecting the script and the playwright''s purpose", "Ignoring the text", "Replacing the story"]'::jsonb,1,'Fidelity to intent matters.','original'),
('117.318.c.3.D',4,'A student reviews a production plan including research notes, rehearsal schedule, technical designs and blocking. She is doing what?','["Painting scenery", "Selling tickets", "Analyzing production plans", "Auditioning"]'::jsonb,2,'Plans coordinate all elements.','original'),
('117.318.c.3.D',4,'Why is a rehearsal schedule an important part of a production plan?','["It writes lines", "It decorates the lobby", "It sells seats", "It allocates time for each scene and technical element"]'::jsonb,3,'Scheduling organizes the work.','original'),
('117.318.c.3.E',4,'A student casts a one-act, directs rehearsals and produces a performance for the school. She is demonstrating what?','["Leadership", "Avoidance", "Procrastination", "Isolation"]'::jsonb,0,'Leading a production shows leadership.','original'),
('117.318.c.3.E',4,'Which responsibility belongs to a producer?','["Playing the lead", "Managing budget, schedule and resources", "Writing lyrics", "Running the lights alone"]'::jsonb,1,'Producers coordinate resources.','original'),
('117.318.c.3.F',4,'A student devotes herself to becoming an expert in scenic design, taking on larger projects with discipline. She is applying what?','["Disorder", "Casual interest only", "Expertise in a production area with responsibility", "Avoidance"]'::jsonb,2,'Expertise requires commitment.','original'),
('117.318.c.3.F',4,'Which demonstrates professional-level artistic discipline?','["Missing deadlines", "Arriving unprepared", "Avoiding feedback", "Preparing thoroughly and following through on commitments"]'::jsonb,3,'Discipline is reliability.','original'),
('117.318.c.4.A',4,'A student evaluates how the Great Migration influenced African American theatre in northern cities. She is evaluating what?','["Historical and cultural influences on theatre", "Ticket revenue", "Lighting gels", "Seat styles"]'::jsonb,0,'Social history shapes drama.','original'),
('117.318.c.4.A',4,'Evaluating the impact of the printing press on drama involves considering what?','["Ticket booths", "How wider access to scripts changed theatre", "Set weight", "Costume sizes"]'::jsonb,1,'Printing spread plays.','original'),
('117.318.c.4.B',3,'A student shows how theatrical storytelling appears in advertising, news and video games. She is analyzing what?','["Staging risks", "Seating plans", "Theatre''s role in daily life and its influence on other media", "Box office rules"]'::jsonb,2,'Theatrical ideas permeate media.','original'),
('117.318.c.4.B',3,'Which example shows daily-life use of theatre skills?','["An empty theatre", "A broken light", "A closed stage", "A manager using presentation skills in a meeting"]'::jsonb,3,'Skills carry over.','original'),
('117.318.c.4.C',4,'A student stages a scene live, records it, edits the recording and analyzes how each context shapes meaning. She is employing and evaluating what?','["Live theatre and film in contrasting contexts", "Merchandise", "Ticket sales", "Parking"]'::jsonb,0,'Contrast shows differing impact.','original'),
('117.318.c.4.C',4,'What is a unique strength of live theatre compared with film?','["Retakes", "Shared real-time presence between actors and audience", "Post-production", "Camera angles"]'::jsonb,1,'Live presence is distinctive.','original'),
('117.318.c.4.D',4,'A student researches how Brecht''s epic theatre influenced political theatre worldwide. She is researching what?','["Parking policy", "Costume prices", "Influences of world drama and its key figures", "Lobby design"]'::jsonb,2,'World drama shapes practice.','original'),
('117.318.c.4.D',4,'Which dramatist wrote A Doll''s House?','["Samuel Beckett", "Sophocles", "Anton Chekhov", "Henrik Ibsen"]'::jsonb,3,'Ibsen wrote A Doll''s House.','original'),
('117.318.c.4.E',4,'A student researches Asian American theatre companies and their impact on U.S. stages. She is researching what?','["The multicultural heritage of drama in the United States", "Costume cost", "One genre only", "Ancient Rome"]'::jsonb,0,'U.S. theatre includes diverse companies.','original'),
('117.318.c.4.E',4,'Which playwright is known for Fences?','["Neil Simon", "August Wilson", "Eugene O''Neill", "Edward Albee"]'::jsonb,1,'Wilson wrote Fences.','original'),
('117.318.c.4.F',4,'The Group Theatre of the 1930s brought new acting approaches to American stages. This is an example of what?','["An ancient ritual", "A film technique", "A U.S. innovation in the performing arts", "A European tradition only"]'::jsonb,2,'The Group Theatre advanced American acting.','original'),
('117.318.c.4.F',4,'Which technique was popularized in the U.S. by Lee Strasberg and the Actors Studio?','["Kabuki kata", "Noh mask work", "Commedia lazzi", "Method acting"]'::jsonb,3,'The Actors Studio promoted Method acting.','original'),
('117.318.c.5.A',3,'A student evaluates audience behavior at an outdoor festival, a formal play and a school assembly, then practices behavior suited to each. She is doing what?','["Evaluating and practicing appropriate audience behavior", "Ignoring context", "Acting disrespectfully", "Avoiding events"]'::jsonb,0,'Etiquette varies by setting.','original'),
('117.318.c.5.A',3,'Why does audience behavior matter to performers?','["It sets ticket prices", "It affects the energy and focus of the show", "It changes the script", "It moves the stage"]'::jsonb,1,'Audiences affect performances.','original'),
('117.318.c.5.B',4,'A student writes an essay arguing that theatre builds empathy and civic awareness, citing performances she has seen. She is doing what?','["Copying a review", "Dismissing theatre", "Defending theatre as an art form", "Avoiding opinions"]'::jsonb,2,'Arguments support the art form.','original'),
('117.318.c.5.B',4,'Valuing oneself as a creative being involves what?','["Doubting every idea", "Copying others", "Avoiding risk", "Recognizing one''s ideas and contributions as meaningful"]'::jsonb,3,'Self-valuing supports artistry.','original'),
('117.318.c.5.C',4,'A student compares how a novel and its stage adaptation convey a character''s thoughts, noting what is gained and lost. She is doing what?','["Comparing literary and dramatic forms through evaluation", "Counting acts", "Reviewing a menu", "Reading a coupon"]'::jsonb,0,'Adaptation shows differing techniques.','original'),
('117.318.c.5.C',4,'What is a challenge when adapting a novel''s inner thoughts to the stage?','["Audiences cannot hear", "Showing internal life through action, voice and design", "There is no story", "There are no characters"]'::jsonb,1,'Stage must externalize thoughts.','original'),
('117.318.c.5.D',4,'A student compares how a theme is communicated in a play, a film, a song and a mural. She is comparing what?','["Parking", "Posters only", "Elements and communication methods across art forms", "Ticket stubs"]'::jsonb,2,'Each form uses distinct tools.','original'),
('117.318.c.5.D',4,'Which method of communication is shared by theatre and music?','["Printed text only", "Sculpture", "Static imagery", "Live performance in real time"]'::jsonb,3,'Both are performed live.','original'),
('117.318.c.5.E',3,'A student interviews a theatre administrator and a high school drama teacher to compare their career paths. She is doing what?','["Evaluating career and avocational opportunities", "Guessing", "Skipping research", "Ignoring options"]'::jsonb,0,'Interviews inform career evaluation.','original'),
('117.318.c.5.E',3,'Which is an avocational opportunity in theatre?','["Corporate producing", "Acting in a community theatre production on weekends", "Full-time teaching", "Union stage management"]'::jsonb,1,'Avocations are pursued for enjoyment.','original'),
('117.318.c.5.F',4,'A senior publishes a website with annotated production photos, research findings and reflective essays. She is employing what?','["A paper map", "A coupon", "Technology to communicate and present theatre experiences", "A tuning fork"]'::jsonb,2,'Digital portfolios present learning.','original'),
('117.318.c.5.F',4,'Which feature improves a digital theatre portfolio''s usefulness for admissions?','["Random uploads", "No captions", "Broken links", "Organized work samples with clear descriptions"]'::jsonb,3,'Organization helps reviewers.','original'),
('117.318.c.5.G',4,'A senior links her stage management experience to goals in project management and event planning. She is appraising what?','["Personal theatre skills in relation to higher education and careers", "Seat counts", "Sports scores", "Weather"]'::jsonb,0,'Skills transfer to many fields.','original'),
('117.318.c.5.G',4,'Which theatre skill transfers best to a leadership career?','["Avoiding teams", "Coordinating people and deadlines under pressure", "Hiding from tasks", "Skipping planning"]'::jsonb,1,'Production leadership transfers.','original'),
('117.318.c.5.H',3,'A graduating senior assembles a page listing roles, crew positions, awards and training. She is creating a ___.','["Cue sheet", "Prompt book", "Theatrical resume", "Playbill advertisement"]'::jsonb,2,'A resume lists experience.','original'),
('117.318.c.5.H',3,'Which is an appropriate item in a theatre portfolio for an audition?','["Menu", "Utility bills", "Class schedules", "Headshot, resume and recorded monologue"]'::jsonb,3,'Audition portfolios feature these materials.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
